def prepare_unique_emails(apps, schema_editor):
    User = apps.get_model("accounts", "User")
    seen = set()
    for user in User.objects.order_by("pk"):
        base = (user.email or f"{user.username}@invalid.local").strip().lower()
        candidate = base
        counter = 1
        while candidate in seen:
            local, separator, domain = base.partition("@")
            candidate = f"{local}+{counter}@{domain}" if separator else f"{base}-{counter}@invalid.local"
            counter += 1
        seen.add(candidate)
        if user.email != candidate:
            user.email = candidate
            user.save(update_fields=["email"])


